INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('love-maps-001', 'love-maps', 'What’s been taking up the most room in your head this week, and why?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-002', 'love-maps', 'Describe a small moment from the past few days that you’d gladly live through again. What made it so good?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-003', 'love-maps', 'What’s something you’re looking forward to right now, and what exactly are you picturing when you think about it?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-004', 'love-maps', 'Describe the cast of characters in your daily life right now. Who makes your days easier, and who makes them more complicated?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-005', 'love-maps', 'What have you been curious about lately — a question, a subject, a skill, a mystery? How did it first catch your attention?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-006', 'love-maps', 'When your mind is free to wander — on a walk, in the shower, just before sleep — where does it tend to go?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-007', 'love-maps', 'What’s something you find beautiful that most people walk right past? Help {partner} see it the way you do.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-008', 'love-maps', 'What have you been enjoying lately that {partner} might not know about — a song, a place, a show, a new habit, a thought you keep coming back to?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-009', 'love-maps', 'What’s something you’ve cared about for a long time — a craft, a team, a cause — that {partner} has only seen from the outside? Give them a tour.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-010', 'love-maps', 'What’s a story you love telling about yourself? What do you think it says about who you are?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-011', 'love-maps', 'What are you in the middle of right now — a project, a decision, a change, a question — that {partner} has only heard pieces of? Fill in the rest.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-012', 'love-maps', 'What used to be true about you that {partner} might still assume is true? What’s true now instead?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-013', 'love-maps', 'Which season of your life does {partner} know only the headlines of? Tell it in fuller detail, including how it felt to live it.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-014', 'love-maps', 'Describe a turning point — a choice, a move, a job, a chance meeting — that sent your life in a new direction. Who were you before it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-015', 'love-maps', 'Who is someone important to you that {partner} hasn’t really gotten to know yet? Introduce them properly — what they’re like, and what they mean to you.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-016', 'love-maps', 'Who has known you the longest, and what do they understand about you that took {partner} time to learn — or that {partner} is still learning?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-017', 'love-maps', 'Whose troubles are you helping to carry right now — a friend’s, a relative’s, a coworker’s? What is that like for you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-018', 'love-maps', 'What’s a small thing that matters far more to you than anyone would guess? Explain why it does.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-019', 'love-maps', 'What have you changed your mind about in the last few years — about people, the world, or yourself — and what changed it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-020', 'love-maps', 'What’s a part of your personality it took you a long time to accept? How do you feel about it now?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-021', 'love-maps', 'What’s a memory you return to often, even though nothing dramatic happens in it? Why do you think it stays with you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-022', 'love-maps', 'What’s been on your mind about the wider world lately — the news, your community, the future? How has it been sitting with you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-023', 'love-maps', 'If someone shadowed you through an ordinary day, what would they never guess about what’s going on inside you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-024', 'love-maps', 'What does a really good day look like for you these days, and how is that different from a few years ago?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-025', 'love-maps', 'What’s a moment from before we met that you wish {partner} could have witnessed? What would they have seen in you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-026', 'love-maps', 'What’s a worry that’s been sitting in the back of your mind lately? Describe it, even if it seems unreasonable once it’s written down.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-027', 'love-maps', 'What’s something about your inner life you’ve never quite found the words to explain to {partner}? Try now.', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-028', 'love-maps', 'What part of your story do you usually skip over or tell lightly? Tell it here the way it actually felt.', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-029', 'love-maps', 'What’s something about you that people often misunderstand — maybe even {partner}, at times? What’s the truer version?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-030', 'love-maps', 'If {partner} could spend one hour inside your head on a hard day, what would you most want them to notice?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-031', 'love-maps', 'What’s a loss — a person, a place, a plan, a version of yourself — that still lives in you more than most people realize?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-032', 'love-maps', 'What’s something you secretly hope is true about you but can’t quite believe yet? What would it mean if it were?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-033', 'love-maps', 'What are you still trying to prove, and to whom? What would it feel like to stop?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-034', 'love-maps', 'What’s a fear you’ve carried for a long time, and how has it steered the choices you make?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('love-maps-035', 'love-maps', 'What’s a memory that still makes you wince? Write a few kind lines to the version of you who lived it.', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-001', 'appreciation', 'Think of something thoughtful {partner} did recently, however small. What does it reveal about the kind of person they are?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-002', 'appreciation', 'Describe a recent moment when you caught yourself admiring {partner}. What were they doing, and what struck you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-003', 'appreciation', 'What’s a quality of {partner}’s that people notice right away, and one you only discovered up close?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-004', 'appreciation', 'Which of {partner}’s talents do they tend to brush off or play down? Make the case for it.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-005', 'appreciation', 'What’s something about {partner} you’ve grown so used to that you rarely notice it anymore? Describe it as if seeing it for the first time.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000)
INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('appreciation-006', 'appreciation', 'Tell the story of the day we met — or the day you first really noticed {partner} — from your side, including one detail you’ve never mentioned.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-007', 'appreciation', 'What was your first impression of {partner}? What did you get right, and what did you have completely wrong?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-008', 'appreciation', 'Which of {partner}’s quirks did you once find puzzling and now find endearing? How did that change happen?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-009', 'appreciation', 'Describe a time you watched {partner} handle something hard with more grace, patience, or good humor than you expected. What did you learn about them?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-010', 'appreciation', 'What do you admire about the way {partner} treats other people — friends, family, strangers, people who can do nothing for them?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-011', 'appreciation', 'When did you realize you respected {partner} — not just liked or loved them, but respected them? What happened?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-012', 'appreciation', 'If you had to show someone who {partner} really is with one story instead of a list of adjectives, which story would you tell?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-013', 'appreciation', 'Describe a moment you were proud of {partner} that you never fully told them about. What made you so proud?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-014', 'appreciation', 'When have you felt most appreciated by {partner}? What exactly did they say or do that reached you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-015', 'appreciation', 'What’s something we’ve figured out together that you’re genuinely proud of? What does it say about us as a pair?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-016', 'appreciation', 'What do you love about the way {partner}’s mind works — how they notice things, solve problems, or make sense of the world?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-017', 'appreciation', 'What’s a way {partner} has grown since you’ve known them that really impresses you? What do you think made it possible?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-018', 'appreciation', 'Picture an ordinary evening in our life together. What about it would you never want to take for granted?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-019', 'appreciation', 'What’s a choice {partner} has made — about work, family, or how to live — that took real courage? What did it ask of them?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-020', 'appreciation', 'When have you seen {partner} at their most vulnerable? What moved you about them in that moment?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-021', 'appreciation', 'Write about a time {partner} saw you at your worst and stayed kind. What did that mean to you then, and what does it mean now?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-022', 'appreciation', 'Where has {partner} been patient with you for a long time — with a habit, a struggle, a slow change? Thank them for it here.', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-023', 'appreciation', 'What do you admire about {partner} that you’ve never said out loud — because it felt too sentimental, too obvious, or too big? Say it now.', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-024', 'appreciation', 'What has being loved by {partner} taught you about what you deserve?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('appreciation-025', 'appreciation', 'Of everyone you could have ended up with, what is it about {partner}, specifically, that makes you glad it’s them?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-001', 'connection', 'How do you most like {partner} to reach for you on an ordinary day — a question, a joke, a hand on your shoulder, an offer to help? What makes those feel good?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-002', 'connection', 'What are the small ways {partner} reaches for you during the day — a look, a text, a sigh, a story? Which do you notice most, and which might slip past you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-003', 'connection', 'What little things in your day make you want to tell {partner} about them right away? Describe a few recent ones.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-004', 'connection', 'When you have good news, what kind of reaction from {partner} makes it feel even better? Describe a response that makes you feel truly celebrated.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-005', 'connection', 'Describe an ordinary moment between us recently that turned out to be quietly lovely. What made it work?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-006', 'connection', 'What’s a message from {partner} that brightened your day? Why do you think it stuck with you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-007', 'connection', 'Describe a time {partner} remembered something small you’d mentioned in passing. How did it feel to know they’d held onto it?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-008', 'connection', 'What’s a tiny ritual — five minutes or less — you’d love for us to share every day? What would it give you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-009', 'connection', 'Since we don’t share a home, which small ways of staying in touch make you feel closest to {partner}, and which have started to feel routine?', 1, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('connection-010', 'connection', 'When has {partner} understood what you meant even though you said it badly? What did they pick up on?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-011', 'connection', 'Think of a time you celebrated {partner}’s good news in a way that truly reached them. What did you do, and how could you tell?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-012', 'connection', 'What question could {partner} ask at the end of a day that would open you up more than “How was your day?” Answer it for today.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-013', 'connection', 'In which moments does it matter most to you that {partner} sets everything aside and is fully present? Describe one.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-014', 'connection', 'When one of us misses the other’s small attempt to connect, what’s a gentle way to circle back to it? What would work for you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-015', 'connection', 'When {partner} reaches for you while you’re absorbed in something — your phone, work, a show — how do you usually respond? How would you like to?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-016', 'connection', 'If you want closeness but don’t want to ask for it outright, what do you tend to do instead? How might {partner} recognize it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-017', 'connection', 'When you bring {partner} a worry or an idea, which responses make you feel taken seriously? Describe one that stayed with you.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-018', 'connection', 'Which conversations leave you feeling closest to {partner} afterward? What do they tend to have in common?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-019', 'connection', 'What makes time in the same room, each doing our own thing, feel connected rather than distant?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-020', 'connection', 'What’s something {partner} cares about that you’d like to show more interest in? What might that look like this week?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000)
INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('connection-021', 'connection', 'Which part of our day together feels most rushed or easily skipped? What small change might help us really meet there?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-022', 'connection', 'Which kinds of attention from {partner} do you tend to brush off, even though part of you would like more of them?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-023', 'connection', 'What does feeling cared for by {partner} look like on an ordinary day — not a birthday or a crisis, just a regular Tuesday?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-024', 'connection', 'Think of a small moment when you reached for {partner} and it didn’t quite land. What were you hoping for, and what might have helped?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-025', 'connection', 'What’s a small kind of attention you’d love more of but have never quite asked for? Describe it, and what it would mean to you.', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-026', 'connection', 'What’s a part of your day you’ve stopped telling {partner} about? What made you stop, and what would make you want to start again?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-027', 'connection', 'When {partner} shares something exciting, what can get in the way of your full enthusiasm — tiredness, worry, envy, distraction? Write honestly.', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-028', 'connection', 'What do you wish {partner} understood about the way you show care — the things you do that might not look like love from the outside?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-029', 'connection', 'How do you think {partner} would describe the way you respond when they reach for you? Where might they be right, and what would you want them to know?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('connection-030', 'connection', 'Picture a week made only of our small moments — texts, passing comments, quick hugs. What do they say about us now, and what would you want them to say?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-001', 'security', 'When do you feel safest with {partner}? Describe a recent moment and what made it feel that way.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-002', 'security', 'Recall a time {partner} comforted you in just the right way. What did they do, and why did it work for you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-003', 'security', 'When something between us has hurt you, how do you usually let {partner} know, if you do? What makes it hard to reach for them right then?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-004', 'security', 'Even when {partner} sees a situation differently, what helps you feel that your feelings make sense to them?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-005', 'security', 'How do you like to be comforted when you’re sad, and how is that different from what you need when you’re anxious or angry?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-006', 'security', 'What’s a tender spot for you, somewhere you bruise more easily than {partner} might realize? How would you like them to handle it?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-007', 'security', 'Which kinds of teasing feel warm and affectionate to you, and where does teasing stop feeling playful?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-008', 'security', 'When you sense distance growing between you and {partner}, how do you usually react, and what are you most wanting from them in that moment?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-009', 'security', 'Many couples fall into a familiar loop when they feel distant: one reaches, the other retreats, or both go quiet. What does ours look like, step by step?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-010', 'security', 'What helps you believe we can have a hard conversation and still be okay with each other afterward?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-011', 'security', 'When you’re feeling unsure about us, which words or actions from {partner} actually reassure you, and which well-meant ones don’t quite reach you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-012', 'security', 'What old fear gets stirred up in you when things feel shaky between us, and what does it push you to do?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-013', 'security', 'Needing space can mean many things. What does it usually mean for you, and what would help {partner} understand it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-014', 'security', 'What helps you trust that {partner} will come back to you when they need some space?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-015', 'security', 'If someone else has hurt or criticized you, what kind of response from {partner} helps you feel less alone with it?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-016', 'security', 'When, if ever, do you worry about being too much for {partner}, or not enough? What helps quiet that worry?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-017', 'security', 'What kinds of moments make you wonder where you stand with {partner}, and what helps you feel steady again?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-018', 'security', 'How do you try to comfort {partner} when they’re hurting, and how do you tell whether it’s helping?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-019', 'security', 'How does your body tell you whether you feel safe or on guard with {partner}? What do you notice in each state?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-020', 'security', 'When we get stuck in a painful pattern, what do you imagine {partner} is feeling underneath their reaction? What might they need from you in that moment?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-021', 'security', 'What helps you feel sure of us when we’re apart for a while, and what tends to make you uneasy?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-022', 'security', 'What do you think {partner} most needs in order to feel safe with you, and where do you think you’re getting it right or missing it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-023', 'security', 'Picture us sliding into one of our old patterns of distance. What could help us notice it early and find our way back to each other?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-024', 'security', 'Think of a time you needed {partner} and they couldn’t be there in the way you hoped. What would help that memory feel more settled now?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-025', 'security', 'What kind of physical comfort helps when you’re upset, and when would you rather not be touched?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-026', 'security', 'Which of your feelings come easily when you’re with {partner}, and which are harder to let them see? What makes the difference?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-027', 'security', 'When you’re about to tell {partner} something hard about yourself, what reaction do you brace for, and what reaction do you hope for?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-028', 'security', 'What part of yourself do you still hesitate to show {partner}, and what would make it feel safe enough to share?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-029', 'security', 'How has your sense of safety with {partner} changed over our time together, and what has shaped it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('security-030', 'security', 'Where does leaning on {partner} feel natural to you, and where does it still feel risky? Why do you think that is?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000)
INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('trust-001', 'trust', 'What’s the first moment you remember knowing you could rely on {partner}? Tell the story.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-002', 'trust', 'Trust is about more than faithfulness. What else does it mean to you, and which small, everyday moments build it up or quietly wear it down?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-003', 'trust', 'Where do you see {partner}’s words and actions line up most clearly, and what does that consistency mean to you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-004', 'trust', 'In the everyday choices we make, like what we say yes to, what we turn down, and who we call first, where do you see our commitment to each other?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-005', 'trust', 'Where do you draw the line between a close friendship and something that would feel like a betrayal? How did you arrive at that line?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-006', 'trust', 'Where do you stand on small, kind untruths, like saying you love a gift you don’t? When does honesty matter more to you than comfort?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-007', 'trust', 'When you feel a flicker of jealousy, what is it usually trying to tell you, and what helps you handle it well?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-008', 'trust', 'What’s something you once kept to yourself in our relationship that you later wished you’d shared? What held you back?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-009', 'trust', 'When we’re with family or friends, what helps you feel that we’re on the same team? Describe a time you felt it clearly.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-010', 'trust', 'When did “you and me” start to feel like “us” for you, and what does that “us” mean to you now?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-011', 'trust', 'Within a relationship, where does healthy privacy end and secrecy begin for you? Think about phones, messages, friendships, or time alone.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-012', 'trust', 'How much do you like to know about each other’s plans and whereabouts day to day, and what makes that feel caring rather than controlling?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-013', 'trust', 'How do you think trust gets rebuilt after it’s been bent or broken, whether between us or in a relationship you’ve watched up close?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-014', 'trust', 'What experiences taught you to be careful about trusting people, and how does that caution show up with {partner}?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-015', 'trust', 'What feels fine to share with friends or family about our relationship, and what would you rather keep between the two of us?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-016', 'trust', 'When something {partner} does lands badly, what helps you trust that their intentions were good?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-017', 'trust', 'What’s something you’ve shared with {partner} in confidence, and how did the way they handled it affect your trust?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-018', 'trust', 'Attraction to other people can happen even in committed relationships. How would you want us to talk about it if it did?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-019', 'trust', 'Who showed you what loyalty looks like, in your family or beyond it? Write about them and what loyalty means to you now.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-020', 'trust', 'What’s the hardest kind of honesty for you to offer {partner}, and what would make it easier?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-021', 'trust', 'In what ways do you feel trusted by {partner}, and where would you like to feel more trusted?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-022', 'trust', 'Recall a time trust between us wobbled, even a little. What helped steady it, and what, if anything, still needs attention?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-023', 'trust', 'What’s one thing about you that you want {partner} to never have to wonder about?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-024', 'trust', 'When you imagine us many years from now, what do you most want to protect about who we are together today?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-025', 'trust', 'What helps you value what we have instead of measuring us against other couples or imagined alternatives?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-026', 'trust', 'Which sacrifices you’ve made for us feel like gifts, and which still feel like losses?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-027', 'trust', 'Where do you trust {partner}’s judgment completely, and where do you find yourself double-checking? What do you think is behind the difference?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-028', 'trust', 'Which promise to {partner}, big or small, do you find hardest to keep, and what gets in the way?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('trust-029', 'trust', 'Since we don’t live together, much of {partner}’s daily life happens out of your sight. What helps you feel trusting and connected across that gap?', 2, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('trust-030', 'trust', 'What do you find yourself choosing about us again and again, and what keeps us steady on the days when choosing feels hard?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-001', 'conflict', 'Choose an argument we’ve had more than once. Underneath the surface topic, what feeling or need of yours is really at stake?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-002', 'conflict', 'What helps you calm down when a conversation starts getting heated, and how can {partner} make that easier?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-003', 'conflict', 'When {partner} needs to raise something that’s bothering them, what way of bringing it up makes it easiest for you to really listen?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-004', 'conflict', 'Recall a disagreement that ended up bringing us closer. What turned it around?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-005', 'conflict', 'Think about something we see differently. What part of your view feels essential to you, and where do you have more room to bend than {partner} might guess?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-006', 'conflict', 'What’s a small gesture, phrase, or bit of humor that can soften things between us in the middle of an argument?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-007', 'conflict', 'Take a recent disagreement and describe it the way a fair, caring friend of both of us would see it. What would they notice that we missed?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-008', 'conflict', 'When {partner} raises a concern about something you did, what helps you stay curious instead of rushing to defend yourself?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-009', 'conflict', 'What does {partner} do during disagreements that you quietly appreciate, even if you’ve never said so?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-010', 'conflict', 'What word, tone, or look can set you off faster than you’d expect, and what deeper hurt or worry do you think it touches?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000)
INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('conflict-011', 'conflict', 'Where and when do our hard conversations tend to go best? What is it about that setting that helps?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-012', 'conflict', 'Pick something small that’s been bothering you and write it as a gentle, specific request that {partner} could actually act on.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-013', 'conflict', 'Most couples have a few differences that never fully go away. Which of ours comes to mind, and how could we keep talking about it with more ease and kindness?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-014', 'conflict', 'What makes an apology feel real to you? Describe a time someone apologized to you and it truly landed.', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-015', 'conflict', 'Looking back at a recent disagreement, what part of it can you honestly own, and how would you put that into words for {partner}?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-016', 'conflict', 'When an argument gets tense, which of your feelings show on the outside, and which more tender ones are underneath?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-017', 'conflict', 'What would a good pause look like for us when an argument gets too heated: how we call it, how long it lasts, and how we find our way back?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-018', 'conflict', 'Imagine a neutral observer who wants the best for both of us. What good might they see coming out of one of our harder disagreements?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-019', 'conflict', 'When a small annoyance comes up, how do you decide whether to mention it or let it go? How well is that working for you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-020', 'conflict', 'What’s a criticism you’ve made of {partner} that you’d like to rephrase now as what you actually needed?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-021', 'conflict', 'When {partner} reaches out to make peace while things are still tense, what makes it easier for you to accept, and what makes it harder?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-022', 'conflict', 'Where do you find it easy to let {partner}’s view shape a decision, and where is it harder to give ground? What makes the difference?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-023', 'conflict', 'Which lessons about conflict did you absorb growing up that you’re still working to unlearn? How do they show up between us?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-024', 'conflict', 'What helps you hold on to what you respect and love about {partner}, even while we’re disagreeing?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-025', 'conflict', 'Describe one of our recurring arguments as if it were an uninvited guest. What brings it around, what does it tell each of us, and what helps it leave?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-026', 'conflict', 'What, if anything, from a past disagreement still stings, and what would help you finally set it down?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-027', 'conflict', 'What does forgiveness look like for you in practice, and what makes it easier or harder to let something go with {partner}?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-028', 'conflict', 'In the heat of an argument, what makes it hard for you to step back and see things as a kind, neutral observer would? What might help next time?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-029', 'conflict', 'When tension builds, what story do you tend to tell yourself about what {partner} is thinking? How does that story compare with what they tell you later?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-030', 'conflict', 'Write about a disagreement we’ve had from {partner}’s point of view, as generously and accurately as you can.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-031', 'conflict', 'When have you given in mostly to keep the peace? How did it feel afterward, and what do you wish you’d said?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-032', 'conflict', 'Since we don’t live together, some of our disagreements happen over text or on calls. What helps those go well, and what tends to make them harder?', 1, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-033', 'conflict', 'What do you think {partner} finds hardest about disagreeing with you? Where might they have a point?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-034', 'conflict', 'When tension between us flares up in front of the kids, how would you like us to handle it in the moment, and how much of the making up should they see?', 2, 'parents', 'research', 'active', 1791676800000, 1791676800000),
  ('conflict-035', 'conflict', 'Which subjects do you tend to steer around with {partner}, and what do you imagine would happen if you brought them up?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-001', 'dreams', 'What did you dream of becoming when you were younger, and what part of that dream is still alive in you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-002', 'dreams', 'What’s a dream that has taken root only in the last few years, and what sparked it?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-003', 'dreams', 'What’s something you’ve done that a younger you would be amazed by, and what dream comes next?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-004', 'dreams', 'Whose life makes you think, “I want some of that”? What part, exactly, and why does it pull at you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-005', 'dreams', 'If paying the bills weren’t a concern, how would you spend your days, and what does that tell you about what you want?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-006', 'dreams', 'Describe an ordinary day in the life you hope we’re living ten years from now. What’s changed, and what’s exactly the same?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-007', 'dreams', 'What’s a dream from your younger years that you’re now glad didn’t come true, and why?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-008', 'dreams', 'What’s one concrete step toward a dream of yours that you could take this month, and how could {partner} make it easier?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-009', 'dreams', 'Which of your dreams has changed shape since you met {partner}, and how do you feel about the change?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-010', 'dreams', 'What’s a dream that keeps coming back to you, year after year, and what do you think it’s trying to tell you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-011', 'dreams', 'When you imagine yourself at eighty, what do you think you’d most regret not having tried?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-012', 'dreams', 'Which responsibilities make your dreams feel far away right now, and what could we rearrange to bring one a little closer?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-013', 'dreams', 'What’s a dream of {partner}’s that you understand least, and what would you love to ask about it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-014', 'dreams', 'When you go after something and it doesn’t work out, what do you need from {partner} in the days that follow?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-015', 'dreams', 'Which of {partner}’s dreams do you most want to see come true, and what could you do to help it along?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000)
INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('dreams-016', 'dreams', 'What dream of yours do you wish {partner} asked about more often, and what would you want to say?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-017', 'dreams', 'What’s a dream you suspect we share but have never really talked about?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-018', 'dreams', 'What’s a dream for us that might sound unrealistic to anyone else but feels right to you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-019', 'dreams', 'What do you need from our life together so your own separate dreams still have room to grow?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-020', 'dreams', 'Which of your dreams were handed to you—by family, culture, or other people’s expectations—and which feel truly your own?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-021', 'dreams', 'What’s a dream you’ve had to let go of, and how can {partner} honor what it meant to you?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-022', 'dreams', 'What longing of yours tends to come out sideways—as a complaint, a sigh, a sore spot—and what dream is underneath it?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-023', 'dreams', 'Which dream of yours do you sometimes feel guilty for wanting, and where does that guilt come from?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-024', 'dreams', 'What do you hope will outlast you—something you made, someone you helped shape, a way of treating people—and why that?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('dreams-025', 'dreams', 'When we’re very old and looking back, what do you hope we’ll say we gave each other?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-001', 'meaning', 'How do you like your birthday to be marked—a big celebration, a quiet day, something in between—and what’s behind that preference?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-002', 'meaning', 'What do you want shared meals to mean in our life—fuel, ceremony, a time to really talk, something else?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-003', 'meaning', 'What’s a tradition you’d love us to invent from scratch, one that doesn’t come from either of our families?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-004', 'meaning', 'Which holiday or season feels most meaningful to you, and what would make it feel truly ours?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-005', 'meaning', 'Think of a gathering you’ve loved—family, friends, neighbors, a community event. What made it feel meaningful, and how could we create more of that?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-006', 'meaning', 'What object in our life together—a gift, a photo, something ordinary—holds the most meaning for you, and what story does it carry?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-007', 'meaning', 'Which place holds the most meaning for us as a couple—where something began, changed, or was decided—and why?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-008', 'meaning', 'What’s a phrase, joke, or symbol that means something only to the two of us, and how did it come to matter?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-009', 'meaning', 'What values do you think we share most deeply, and where do you see them in how we actually live?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-010', 'meaning', 'What’s a ritual we’ve fallen into without ever deciding to, and what does it say about us?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-011', 'meaning', 'If we kept one standing weekly ritual that was just ours, what would you want it to be, and what would it protect for us?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-012', 'meaning', 'How would you like us to mark the big passages in our life—beginnings, endings, recoveries, goodbyes—so they don’t just slip by?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-013', 'meaning', 'Which spiritual or reflective practices matter to you—prayer, meditation, a weekly service, time in nature—and which, if any, would you like us to share?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-014', 'meaning', 'Who counts as family to you now—by blood, by choice, or by time—and how has that circle changed?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-015', 'meaning', 'Of all the roles you play—partner, friend, worker, family member—which feels closest to your heart, and how does our life together support it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-016', 'meaning', 'What part do faith, spirituality, or deeply held convictions play in your life, and how did you arrive where you are?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-017', 'meaning', 'Where do you find awe or a sense of the sacred—in a place of worship, in nature, in music, in people—and when did you last feel it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-018', 'meaning', 'Where do our beliefs about faith, meaning, or what matters most overlap, and where do they differ? How do you want us to hold the differences?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-019', 'meaning', 'What’s a value you’d like our life together to reflect more than it does right now?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-020', 'meaning', 'What gives your life a sense of purpose these days, and how much room does it actually get in your week?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-021', 'meaning', 'Which friends or communities make you feel most like yourself, and how do you want them woven into our life?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-022', 'meaning', 'What kind of neighbors do you want us to be, and what part do you want us to play in the community around us?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-023', 'meaning', 'What do you want the two of us to be known for by the people who know us best?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-024', 'meaning', 'Beyond making each other happy, what do you want our life together to be for?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-025', 'meaning', 'What do you hold sacred, whether or not you’re religious, and how can {partner} honor it?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-026', 'meaning', 'In what ways, if any, does our relationship feel like part of something bigger than the two of us, and what gives it that weight?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-027', 'meaning', 'What big questions—about faith, death, purpose, or how to live—are you still wrestling with, and what would it be like to wrestle with them together?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-028', 'meaning', 'When do you feel most sure that your life matters, and when do you find yourself doubting it?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-029', 'meaning', 'How would you like us to remember the people we’ve lost, so they stay part of our life together?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('meaning-030', 'meaning', 'What’s a principle you’d want us to stand up for together, even if it cost us something?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000)
INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('growth-001', 'growth', 'What’s something unfamiliar we could try this month — a food, a neighborhood, an event neither of us would usually pick? What makes it appealing to you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-002', 'growth', 'Describe a time we tried something new together. What did you notice about {partner} — or about us — that you hadn’t seen before?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-003', 'growth', 'What’s something {partner} knows how to do that you’d love them to teach you? What might you learn besides the skill itself?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-004', 'growth', 'What are you learning right now — from a book, a class, a job, a mistake, a person — that you’d like {partner} to know about?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-005', 'growth', 'Where in our life together are we running most on autopilot? What’s one small way you’d like to shake it up, and why?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-006', 'growth', 'When did you last feel like a beginner at something? How did you handle not being good at it yet?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-007', 'growth', 'Who do you know who keeps growing and trying new things as the years go by? What do you admire in how they do it?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-008', 'growth', 'What’s something you used to be afraid of or bad at that you’ve since gotten better at? How did that happen?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-009', 'growth', 'Who are you becoming right now? Describe the version of yourself you seem to be slowly growing into.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-010', 'growth', 'What’s a recent experience that made you feel more alive or more like yourself? What do you think it woke up in you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-011', 'growth', 'What does {partner} bring out in you that you like? Describe a moment you saw that side of yourself because of them.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-012', 'growth', 'What’s something we could learn side by side, neither of us with a head start? What do you imagine we’d discover about each other along the way?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-013', 'growth', 'How has being with {partner} widened your world — new people, ideas, places, tastes, or ways of seeing things?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-014', 'growth', 'How have you changed since we got together — in ways you’re glad about, and in ways you’re still getting used to?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-015', 'growth', 'Where in your life do you want {partner} to nudge you forward, and where would you rather they trust you to find your own way?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-016', 'growth', 'What’s a rut you’ve slipped into lately — a habit, a mood, a way of spending your time? What might help you climb out of it?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-017', 'growth', 'What’s a challenge that would stretch us both — physically, creatively, or mentally — that you’d like us to take on together? Why that one?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-018', 'growth', 'What’s something we used to do together that has quietly faded away? What would it take to bring it back, or to replace it with something new?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-019', 'growth', 'When has {partner} believed in you before you believed in yourself? What did that belief make possible?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-020', 'growth', 'What’s a part of yourself you’re hesitant to grow into because it might change things — including us?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-021', 'growth', 'What’s an old version of yourself that still shows up around {partner} sometimes? What helps you return to who you are now?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-022', 'growth', 'When has {partner}’s growth been hard for you — leaving you feeling behind, left out, or unsure where you fit? What helped, or what would?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-023', 'growth', 'What would the best version of you bring to our relationship that you struggle to offer right now? What’s standing in the way?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-024', 'growth', 'What’s something {partner} does better than you that’s a little hard for you to admit? What does it stir up, and what could you learn from them?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('growth-025', 'growth', 'In what ways might you have held {partner} back, even without meaning to? What would it look like to support them more fully?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-001', 'origins', 'What did affection look like in the home you grew up in, and how much of that do you carry with you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-002', 'origins', 'Picture an ordinary weeknight from your childhood. Who was around, what happened at dinnertime, and what was the mood like?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-003', 'origins', 'What’s something your family did that you assumed was completely normal, until you saw how other families lived?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-004', 'origins', 'What’s a story your family tells again and again, and what does it say about who they are, or who they want to be?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-005', 'origins', 'When, if ever, did your family have fun together while you were growing up, and which moments still stand out?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-006', 'origins', 'Which of your habits—how you cook, celebrate, unwind, or spend a Sunday—came straight from the people who raised you, and which feel most like home?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-007', 'origins', 'Which feelings were welcome in your family growing up, and which ones did you learn to keep to yourself?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-008', 'origins', 'When there was conflict in your home growing up, what did it look and sound like from where you stood, and how did people find their way back, if they did?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-009', 'origins', 'What did your family teach you, in words or by example, about asking for help? How does that show up when you need {partner}?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-010', 'origins', 'What did the adults around you say about love and relationships, and how did that compare with what you actually saw?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-011', 'origins', 'What unspoken rules did your family live by, and which ones still quietly shape you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-012', 'origins', 'What role did you play in your family growing up—the peacemaker, the responsible one, the comic relief, the quiet one—and where does it still show up?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-013', 'origins', 'When you look at the way we love each other, where do you see your family’s fingerprints, for better and for worse?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-014', 'origins', 'What’s a tradition from the family you grew up in that you’d love to carry into our life together, and one you’re glad to leave behind?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-015', 'origins', 'What did holidays feel like when you were growing up, and which of those feelings do you find yourself chasing or avoiding now?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000)
INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('origins-016', 'origins', 'When it comes to holidays and family visits, what feels fair to you, and what do you want to protect for just the two of us?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-017', 'origins', 'Which part of your cultural, religious, or regional heritage do you most want {partner} to understand, or even share in?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-018', 'origins', 'How has your relationship with the people who raised you changed since you became an adult, and how do you feel about where it stands now?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-019', 'origins', 'What do you wish {partner} understood about your relationship with your siblings, or about growing up as an only child?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-020', 'origins', 'How do you change when you’re back with your family—your voice, your mood, your role—and what do you need from {partner} in those moments?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-021', 'origins', 'What do you enjoy most about {partner}’s family, and what still feels a little unfamiliar to you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-022', 'origins', 'What helps you feel welcome in {partner}’s family, and what, if anything, makes you feel like an outsider?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-023', 'origins', 'If one of our families ever oversteps, who should be the one to speak up, and what would you want that conversation to sound like?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-024', 'origins', 'What did you have to handle at too young an age, if anything, and how does it still show up in the way you take care of others?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-025', 'origins', 'What, if anything, about your family is fine for you to criticize but hard to hear from {partner}? Why do you think that is?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-026', 'origins', 'If you’re comfortable sharing, what’s something from growing up that still shapes how you react when you feel hurt?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-027', 'origins', 'What’s a pattern in your family that you’re determined to end with you, and what has that taken so far?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-028', 'origins', 'If you’re comfortable sharing, what did you need as a child that you didn’t get enough of, and where do you look for it now?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-029', 'origins', 'What do you still hope for from your family, even if you’re not sure it will ever come?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('origins-030', 'origins', 'What did growing up teach you about whether the people you love will stay, and how has being with {partner} confirmed or challenged that?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-001', 'marriage', 'When you hear the word “marriage,” what people, images or feelings come to mind first—and where do you think they came from?', 1, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-002', 'marriage', 'In your own words, what is marriage for? What do you believe it would add to a relationship like ours—if anything at all?', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-003', 'marriage', 'If we decided marriage wasn’t for us, what would you want our commitment to look like instead, and how would you want the people around us to understand it?', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-004', 'marriage', 'Some couples slide toward marriage as the next step; others decide on purpose, whether the answer is yes, no or not yet. Where are we, and what would deciding look like for us?', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-005', 'marriage', 'Before a marriage between us—if one ever happens—which conversations would you want us to have had, and which one do you suspect we’ve been putting off?', 3, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-006', 'marriage', 'How would you know it was the right time to marry? Describe what would need to be true about your life—and what would need to be true in you.', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-007', 'marriage', 'In your view, what should a proposal be—a surprise, a formality, a question already answered together—and what would make one feel true to who we are?', 1, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-008', 'marriage', 'If we married someday, describe the celebration that would feel most like us—or explain why you’d rather skip one altogether.', 1, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-009', 'marriage', 'What expectations from family, faith or culture would weigh on a wedding of ours, if we had one—and how would you want us to handle the ones we don’t share?', 1, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-010', 'marriage', 'If we ever married, how would you want to handle last names—keeping, taking, joining or inventing one—and what does your own name carry for you?', 1, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-011', 'marriage', 'If you wrote vows to {partner} today, which promise would you feel ready to make, and which would you want to understand better before making it?', 3, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-012', 'marriage', 'What did you absorb growing up about what a husband, wife or spouse is supposed to do? Which of those ideas would you keep, and which would you leave behind?', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-013', 'marriage', 'If we married, what do you imagine would change between us, even if daily life looked the same—and what would you most want to keep exactly as it is?', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-014', 'marriage', 'What parts of your independence would you most want to keep inside a marriage, and what would you be glad to share completely?', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-015', 'marriage', 'How connected are marriage and children in your mind, and where did that link—or the lack of one—come from?', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-016', 'marriage', 'Marriage is also a legal and financial merger. How do you feel about that side of it—shared debts, inheritance, a prenup—and what would you want settled first?', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-017', 'marriage', 'Many vows promise to stay through hard times. Which kinds of hardship do you think would test a marriage between us most, and what would staying ask of you?', 3, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-018', 'marriage', 'If one of us wanted marriage more—or sooner—than the other, how would you want us to talk about that gap without pressure or resentment?', 3, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-019', 'marriage', 'What part of you, if any, hesitates about marriage—and what might that hesitation be trying to protect?', 3, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-020', 'marriage', 'If you could ask one long-married couple a single question about marriage, who would you ask, what would you ask, and why that question?', 1, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-021', 'marriage', 'In your mind, how do moving in together, getting engaged and marrying relate—what order, if any, feels right, and why does it matter to you?', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-022', 'marriage', 'Which of our habits during disagreements would you want us to work on before ever promising each other a lifetime—and why that one?', 2, 'unmarried', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-023', 'marriage', 'What about married life has surprised you most—for better or worse—compared with what you pictured before we married?', 1, 'married', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-024', 'marriage', 'Which roles have we settled into as a married couple without ever really choosing them? Which would you like us to look at again, together?', 2, 'married', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-025', 'marriage', 'When the marriages of friends or family struggle or end, how does it affect the way you see ours—and what do you want us to take from it?', 2, 'married', 'research', 'active', 1791676800000, 1791676800000)
INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('marriage-026', 'marriage', 'When you remember deciding to marry {partner}, what were you most sure of, and what were you quietly unsure about? How do both feel now?', 3, 'married', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-027', 'marriage', 'If we renewed our vows ten years from now, what would you want to add that we didn’t know to say the first time?', 1, 'married', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-028', 'marriage', 'When you introduce {partner} as your husband, wife or spouse, what does that word stir in you now, compared with the first time you said it?', 1, 'married', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-029', 'marriage', 'How has being married changed the way you see yourself—or the way other people see and treat you?', 2, 'married', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-030', 'marriage', 'What do you worry could slowly wear down our marriage if we stopped paying attention, and what would you want us to start doing about it now?', 3, 'married', 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-031', 'marriage', 'People often say marriage takes “hard work.” What do you think that work actually is, day to day, and how much of that saying rings true to you?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('marriage-032', 'marriage', 'What have the divorces you’ve witnessed—in your family, among friends, maybe your own—taught you about what a marriage needs in order to last?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('kids-001', 'kids', 'When you picture yourself as a parent someday—or choosing not to be one—what feelings come up first?', 1, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-002', 'kids', 'What draws you toward having children, what gives you pause, and how have those feelings changed over the years?', 2, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-003', 'kids', 'How many children, if any, feels right when you imagine your future—and what experiences shaped that number?', 1, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-004', 'kids', 'When, if ever, would becoming parents feel right to you, and what would you want in place first—in your own life and in ours?', 1, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-005', 'kids', 'If we chose not to have children, what do you imagine our life would be full of instead—and what, if anything, would you grieve?', 3, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-006', 'kids', 'If one of us felt sure about kids and the other didn’t, how would you want us to talk it through so that neither of us felt pushed or left behind?', 3, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-007', 'kids', 'If becoming parents turned out to be a long or painful road for us—fertility struggles, loss, years of waiting—what would you most need from {partner} along the way?', 3, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-008', 'kids', 'What are your honest feelings about adoption, fostering, donors or surrogacy as ways to build a family, and where do those feelings come from?', 2, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-009', 'kids', 'If you became a parent, what kind of parent do you hope you’d be on an ordinary, exhausting weeknight—not just on the good days?', 1, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-010', 'kids', 'If we had a child very different from the one we pictured—in temperament, health, abilities or identity—how do you hope you’d respond, and what would you need?', 3, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-011', 'kids', 'Whether or not we ever raise kids, which of {partner}’s qualities do you think a child would be lucky to grow up around—and where have you seen them?', 1, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-012', 'kids', 'Picture a grown-up child of ours, if we had one. Which three qualities would you most hope they had, and how would we have helped nurture them?', 1, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-013', 'kids', 'How were rules and consequences handled in the home you grew up in, and how would you want discipline to work if we raised children together?', 2, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-014', 'kids', 'If we had kids, what part would you want faith, culture, language or family traditions to play in raising them—and how would we handle the places we differ?', 2, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-015', 'kids', 'What kind of childhood would you hope to give a child—busy or unhurried, closely guided or free-roaming—and what from your own past drives that?', 2, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-016', 'kids', 'If we had kids, how would you want us to share the late nights, the appointments and the invisible to-do lists—and how would we notice if it stopped feeling fair?', 2, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-017', 'kids', 'If we had a baby, how do you picture the first year—who takes time off, for how long, and how work, sleep and money would get rearranged?', 1, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-018', 'kids', 'Say we had children: whose career would bend, how much, and for how long? Describe what would feel fair to you—and what you’d worry about resenting.', 3, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-019', 'kids', 'If children were part of our future, what would you be willing to change about how we spend, save and work—and what would you want to protect no matter what?', 2, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-020', 'kids', 'Many couples feel more distant in the first years with a baby. If we became parents, what would you want us to do from the start to keep our friendship close?', 2, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-021', 'kids', 'What scares you about how children might change us—our time, our closeness, our freedom—and what would help you feel less afraid?', 3, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-022', 'kids', 'What do you fear most about who you might be as a parent, and what would help you trust yourself more?', 3, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-023', 'kids', 'If we had kids, what role would you hope grandparents and other relatives would play in their lives, and where would you want clear boundaries?', 2, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-024', 'kids', 'When you think about having children, whose voices do you hear besides your own—and which of them do you actually agree with?', 2, 'no-kids', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-025', 'kids', 'What part of parenting comes most naturally to you, and what part still stretches you the most?', 1, 'parents', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-026', 'kids', 'How does our wider family fit into our kids’ lives right now—grandparents, aunts, uncles, old friends—and what would you like more of, or less of?', 2, 'parents', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-027', 'kids', 'How has parenting changed our relationship—what has it taken from us for a while, and what has it given us that we never could have planned?', 2, 'parents', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-028', 'kids', 'Looking at how we share the care of our kids—the visible jobs and the invisible ones—what feels fair to you right now, and what quietly doesn’t?', 2, 'parents', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-029', 'kids', 'Where do we parent differently, and what do you respect about {partner}’s approach even when it isn’t yours?', 2, 'parents', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-030', 'kids', 'Years from now, what do you hope our kids will say our family was like—its habits, its sayings, what it stood for—and how close are we to that now?', 2, 'parents', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-031', 'kids', 'As our kids grow and need us in different ways, what do you hope the next chapter of our relationship will hold?', 1, 'parents', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-032', 'kids', 'When do you feel most alone as a parent, and what could {partner} do in those moments that would make the biggest difference?', 3, 'parents', 'research', 'active', 1791676800000, 1791676800000),
  ('kids-033', 'kids', 'What do you worry our kids might one day wish we had done differently—and what, if anything, could we change now?', 3, 'parents', 'research', 'active', 1791676800000, 1791676800000)
INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('kids-034', 'kids', 'Think about the children in our wider world—family, friends’ kids, neighbors. What kind of adult do you want to be in their lives, and why does that matter to you?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('kids-035', 'kids', 'What do you believe children need most from the adults who love them, and what in your own life taught you that?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('home-001', 'home', 'When you imagine us living under one roof, what’s the first ordinary moment you picture—and what feeling comes with it?', 1, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-002', 'home', 'What would moving in together mean to you beyond the logistics, and what would you need to be clear it does—or doesn’t—mean about our future?', 3, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-003', 'home', 'Many couples drift into living together—a toothbrush, then a drawer, then half the closet—without ever deciding. How would you want us to make that choice, if we make it?', 2, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-004', 'home', 'If we lived together someday, what would you want the main reasons to be—and which reasons would make you uneasy if they were the ones really driving it?', 2, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-005', 'home', 'Picture the right moment for us to share a home, if it ever comes. What has changed by then, and how would we know we’d reached it?', 2, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-006', 'home', 'Where would a shared home make the most sense—your place, {partner}’s or somewhere new to both of us—and what would each option ask us to leave behind?', 2, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-007', 'home', 'How would you want to split rent and bills if we lived together—evenly, by income or some other way—and what makes that feel fair to you?', 2, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-008', 'home', 'Which chores do you enjoy, which do you dread, and how would you split them in a shared home—planning and remembering included—so neither of us keeps score?', 1, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-009', 'home', 'Describe your honest standard of clean and tidy, not your aspirational one. Where do you suspect our standards might clash if we lived together?', 2, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-010', 'home', 'If we lived together, what kind of space of your own would you need—a room, a corner, a regular hour alone—and what would it protect for you?', 2, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-011', 'home', 'How do you picture guests in a home we shared—friends dropping by, family staying a week, someone crashing on the couch—and where are your limits?', 1, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-012', 'home', 'What do you need to sleep well—darkness, quiet, a certain bedtime, your own blanket—and which of those would you bend on if we shared a bedroom?', 1, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-013', 'home', 'Which of your daily routines would you want to keep exactly as they are if we moved in together, and which would you happily reshape around {partner}?', 1, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-014', 'home', 'What would make a home feel truly ours, rather than one person’s place with the other’s belongings in it?', 2, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-015', 'home', 'If we combined households, which of your things would be hardest to part with, and how would you want us to decide what stays, what goes and what we choose together?', 1, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-016', 'home', 'What do you think we’d each have to give up to live together, and which of those losses would be hardest for you?', 3, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-017', 'home', 'What worries you most about living together—for us, or for you—and what would help ease that worry?', 3, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-018', 'home', 'If we moved in together and it turned out to be harder than we expected, what would you want us to try before either of us thought about moving out?', 3, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-019', 'home', 'Living together would show {partner} your unedited daily self—moods, habits, bad mornings. Which part of that are you most nervous about, and why?', 3, 'apart', 'research', 'active', 1791676800000, 1791676800000),
  ('home-020', 'home', 'What do you value about having our own places right now, and how would you want to keep some of that if we ever shared a home?', 2, 'apart', 'research', 'active', 1791676800000, 1791676800000),
