INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('money-009', 'money', 'How do you feel about debt—student loans, credit cards, a mortgage—and which kinds seem reasonable to you, which feel dangerous, and why?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('money-010', 'money', 'Which part of your financial story—past or present—feels hardest to say out loud, and what would help you share it with {partner}?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('money-011', 'money', 'How often would you like us to talk about money, and what would make those conversations feel calm and useful rather than tense?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('money-012', 'money', 'Think of a money disagreement that stuck with you—between us, in a past relationship or in your family. What did it reveal about what each person needed?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('money-013', 'money', 'What would you love for us to save toward together, and what would reaching it give us beyond the money?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
