  ('money-015', 'money', 'How much is enough for you? Describe a life that would feel abundant without feeling like a treadmill.', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('money-016', 'money', 'What do you picture for us financially in later life—how much we work, where we live, what we can give—and what would it take to get there?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('money-017', 'money', 'How comfortable are you with financial risk—investing, starting something of your own, changing careers—and where does that comfort or caution come from?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('money-018', 'money', 'What money fear shows up for you even when things are going fine, and where do you think it first took root?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
