  ('money-020', 'money', 'What place would you want giving to have in how we use our money—causes, friends, strangers—and what shaped your sense of what’s generous?', 2, NULL, 'research', 'active', 1791676800000, 1791676800000),
  ('money-021', 'money', 'If someone in your family needed significant money from us—once, or again and again—what would you want us to weigh, and where would you draw the line?', 3, NULL, 'research', 'active', 1791676800000, 1791676800000),
