INSERT INTO questions (id, category, text, depth, audience, source, status, created_at, updated_at) VALUES
  ('intimacy-009', 'intimacy', 'What part do playfulness and laughter play in how you like to be close, and when have they brought us together?', 1, NULL, 'research', 'active', 1791676800000, 1791676800000),
